insert into public.via_programme_requirements(programme_id,subject,detail,source_url,source_name,last_verified_at,academic_year) values('20000000-0000-4000-8000-000000000012','APS by Mathematics subject','Minimum APS 22 with Mathematics, or APS 24 with Mathematical Literacy. Subject minimums also apply.','https://www.uj.ac.za/university-courses/diploma-in-accountancy/','UJ programme requirements','2026-10-18T00:00:00Z',2027);
insert into public.via_programme_requirements(programme_id,subject,detail,source_url,source_name,last_verified_at,academic_year) select p.id,'Confirm full requirements','Check the official programme/faculty guidance for complete requirements. VIA does not calculate an exact match without verified scoring and subject rules.',o.source_url,o.source_name,o.last_verified_at,o.academic_year from public.via_programmes p join public.via_opportunities o on o.id=p.id where not exists(select 1 from public.via_programme_requirements r where r.programme_id=p.id);
insert into public.via_application_cycles(opportunity_id,label,academic_year,source_url,source_name,last_verified_at,fee_note) select p.id,'Confirm intake dates and fees',coalesce(o.academic_year,2027),o.source_url,o.source_name,o.last_verified_at,'Opening date, closing date and application fee are not verified for this listing.' from public.via_programmes p join public.via_opportunities o on o.id=p.id where not exists(select 1 from public.via_application_cycles c where c.opportunity_id in (p.id,p.institution_id) and c.academic_year=coalesce(o.academic_year,2027));
